import { setStatus, updateStatus } from '../../scripts/shared.ts';
import { postProcessTranscriptText } from '../../scripts/spellcheck.ts';

import {
  AUTO_TRANSCRIPT_LOCALE,
  DEFAULT_TRANSCRIPT_LOCALE,
  TRANSCRIPT_LOCALE_SUGGESTIONS,
  normalizeTranscriptLocale,
  resolveTranscriptLocale,
} from './transcript-locale.ts';

const AUDIO_LEVEL_EPSILON = 0.025;
const AUDIO_FFT_SIZE = 256;
const TRANSCRIPT_BROWSER_WARNING_FADE_DURATION_MS = 250;
const TRANSCRIPT_BROWSER_WARNING_VISIBLE_DURATION_MS = 10_000;
const STATUS_RESET_DELAY_MS = 5000;
const TRANSCRIPT_UPLOAD_ENDPOINT =
  'https://api.elevenlabs.io/v1/speech-to-text';
const TRANSCRIPT_UPLOAD_MODEL_ID = 'scribe_v1';
const TRANSCRIPT_DESKTOP_CHROME_ONLY_LABEL =
  'Speech to text works with Google Chrome on desktop only.';
const TRANSCRIPT_DESKTOP_CHROME_ONLY_STATUS =
  'Speech to text works with Google Chrome on desktop only. Download Google Chrome to test the mic transcript feature.';
const TRANSCRIPT_RECOGNITION_UNAVAILABLE_LABEL =
  'Speech to text is unavailable in this Google Chrome browser.';
const TRANSCRIPT_UPLOAD_DEFAULT_MESSAGE =
  'Choose an audio file, select the spoken locale, and enter your ElevenLabs API key.';
const TRANSCRIPT_UPLOAD_IN_PROGRESS_MESSAGE =
  'Uploading audio to ElevenLabs for transcription...';
const TRANSCRIPT_UPLOAD_SUCCESS_MESSAGE =
  'Uploaded audio transcript inserted into the editor.';
const TRANSCRIPT_UPLOAD_EMPTY_API_KEY_MESSAGE =
  'Enter your ElevenLabs API key before starting transcription.';
const TRANSCRIPT_UPLOAD_EMPTY_FILE_MESSAGE =
  'Choose an audio file before starting transcription.';
const TRANSCRIPT_UPLOAD_UNAUTHORIZED_MESSAGE =
  'ElevenLabs rejected the API key. Check the key and try again.';
const TRANSCRIPT_UPLOAD_EMPTY_TRANSCRIPT_MESSAGE =
  'The transcription service returned no text for this audio file.';
const TRANSCRIPT_UPLOAD_LANGUAGE_CODE_ALIASES = new Map([
  ['in', 'id'],
  ['iw', 'he'],
  ['ji', 'yi'],
  ['no', 'nb'],
]);
const TRANSCRIPT_MOBILE_USER_AGENT_RE =
  /android|iphone|ipad|ipod|windows phone|iemobile|opera mini|mobile|tablet/iu;
const TRANSCRIPT_NON_CHROME_BROWSER_RE =
  /\bedg(?:e|ios|a)?\/|\bopr\/|\bopera\b|\bvivaldi\/|\bsamsungbrowser\/|\byabrowser\/|\bduckduckgo\/|\bwhale\/|\bqqbrowser\/|\bucbrowser\/|\bcrios\/|\bfxios\/|\bheadlesschrome\/|\bchromium\/|\belectron\//iu;
const SUPPORT_TRANSCRIPT_RECOGNITION =
  typeof window !== 'undefined' &&
  ('SpeechRecognition' in window || 'webkitSpeechRecognition' in window);

function isLikelyTranscriptMobileBrowser(ownerWindow) {
  const ownerNavigator = ownerWindow?.navigator ?? globalThis.navigator;

  if (!ownerNavigator) {
    return false;
  }

  if (ownerNavigator.userAgentData?.mobile === true) {
    return true;
  }

  const userAgent = String(ownerNavigator.userAgent || '');

  if (TRANSCRIPT_MOBILE_USER_AGENT_RE.test(userAgent)) {
    return true;
  }

  const maxTouchPoints = Number(ownerNavigator.maxTouchPoints || 0);

  return /macintosh/iu.test(userAgent) && maxTouchPoints > 1;
}

function isDesktopGoogleChromeBrowser(ownerWindow) {
  const ownerNavigator = ownerWindow?.navigator ?? globalThis.navigator;

  if (!ownerNavigator || isLikelyTranscriptMobileBrowser(ownerWindow)) {
    return false;
  }

  const brands = Array.isArray(ownerNavigator.userAgentData?.brands)
    ? ownerNavigator.userAgentData.brands
    : [];

  if (brands.length > 0) {
    return brands.some((brandEntry) => {
      const brand = String(brandEntry?.brand || '').trim();

      return /^google chrome$/iu.test(brand);
    });
  }

  if (ownerNavigator.brave) {
    return false;
  }

  const userAgent = String(ownerNavigator.userAgent || '');

  if (!/\bchrome\/\d+/iu.test(userAgent)) {
    return false;
  }

  return !TRANSCRIPT_NON_CHROME_BROWSER_RE.test(userAgent);
}

function getTranscriptSupportState(ownerWindow) {
  const isMobileBrowser = isLikelyTranscriptMobileBrowser(ownerWindow);
  const isDesktopGoogleChrome = isDesktopGoogleChromeBrowser(ownerWindow);
  const isRecognitionAvailable = SUPPORT_TRANSCRIPT_RECOGNITION;

  return {
    isMobileBrowser,
    isDesktopGoogleChrome,
    isRecognitionAvailable,
    isSupported: isDesktopGoogleChrome && isRecognitionAvailable,
    shouldShowBrowserWarning: isMobileBrowser || !isDesktopGoogleChrome,
    shouldShowDownloadChromeWarning: !isMobileBrowser,
  };
}

class TranscriptController {
  constructor({
    application,
    editor,
    monaco,
    onStateChange,
    ownerWindow,
    preferences,
    refs,
    state,
  }) {
    this.application = application;
    this.editor = editor;
    this.monaco = monaco;
    this.onStateChange = onStateChange;
    this.ownerWindow = ownerWindow;
    this.preferences = preferences;
    this.refs = refs;
    this.state = state;

    this.audioContext = null;
    this.audioLevel = 0;
    this.audioSource = null;
    this.audioStream = null;
    this.analyser = null;
    this.browserWarningFadeTimer = 0;
    this.browserWarningHideTimer = 0;
    this.browserWarningMarqueeFrame = 0;
    this.browserWarningResizeObserver = null;
    this.isBrowserWarningHovered = false;
    this.disposables = [];
    this.destroyed = false;
    this.finalizationPromise = Promise.resolve();
    this.frequencyData = null;
    this.interimRange = null;
    this.isEnabled = false;
    this.meterFrame = 0;
    this.pendingRestart = false;
    this.processedFinalResults = new Map();
    this.recognition = null;
    this.recognitionLifecycle = 'inactive';
    this.selection = null;
    this.selectedLocale = normalizeTranscriptLocale(
      this.preferences.loadTranscriptLocalePreference(
        DEFAULT_TRANSCRIPT_LOCALE,
      ),
    );
    this.resolvedLocale = resolveTranscriptLocale(this.selectedLocale);
    this.isUploadInFlight = false;
    this.statusResetTimer = 0;
    this.stopRequested = false;
    this.uploadAbortController = null;
    this.lastLocaleOptionsKey = null;
    this.lastUploadLocaleOptionsKey = null;

    this.handleHostModeChange = this.handleHostModeChange.bind(this);
    this.handleBrowserWarningPointerEnter =
      this.handleBrowserWarningPointerEnter.bind(this);
    this.handleBrowserWarningPointerLeave =
      this.handleBrowserWarningPointerLeave.bind(this);
    this.handleBrowserWarningResize =
      this.handleBrowserWarningResize.bind(this);
    this.handleLocaleChange = this.handleLocaleChange.bind(this);
    this.handleUploadLocaleChange = this.handleUploadLocaleChange.bind(this);
    this.handleUploadTriggerClick = this.handleUploadTriggerClick.bind(this);
    this.handleUploadDialogClose = this.handleUploadDialogClose.bind(this);
    this.handleUploadSubmit = this.handleUploadSubmit.bind(this);
    this.handleUploadDialogCancel = this.handleUploadDialogCancel.bind(this);
    this.handleUploadPermissionInstructionClick =
      this.handleUploadPermissionInstructionClick.bind(this);
    this.handleUploadPermissionDialogCloseClick =
      this.handleUploadPermissionDialogCloseClick.bind(this);
    this.handleToggleClick = this.handleToggleClick.bind(this);
    this.handleToggleMouseDown = this.handleToggleMouseDown.bind(this);
    this.measureAudioLevel = this.measureAudioLevel.bind(this);

    this.initialize();
  }

  initialize() {
    this.attachUiListeners();
    this.attachEditorListeners();
    this.syncHostUi();
  }

  attachUiListeners() {
    if (this.refs.editorTranscriptLocaleSelect instanceof HTMLSelectElement) {
      this.refs.editorTranscriptLocaleSelect.addEventListener(
        'change',
        this.handleLocaleChange,
      );
      this.disposables.push(() => {
        this.refs.editorTranscriptLocaleSelect?.removeEventListener(
          'change',
          this.handleLocaleChange,
        );
      });
    }

    if (this.refs.editorTranscriptToggleBtn instanceof HTMLButtonElement) {
      this.refs.editorTranscriptToggleBtn.addEventListener(
        'mousedown',
        this.handleToggleMouseDown,
      );
      this.refs.editorTranscriptToggleBtn.addEventListener(
        'click',
        this.handleToggleClick,
      );
      this.disposables.push(() => {
        this.refs.editorTranscriptToggleBtn?.removeEventListener(
          'mousedown',
          this.handleToggleMouseDown,
        );
        this.refs.editorTranscriptToggleBtn?.removeEventListener(
          'click',
          this.handleToggleClick,
        );
      });
    }

    if (this.refs.editorTranscriptUploadBtn instanceof HTMLButtonElement) {
      this.refs.editorTranscriptUploadBtn.addEventListener(
        'click',
        this.handleUploadTriggerClick,
      );
      this.disposables.push(() => {
        this.refs.editorTranscriptUploadBtn?.removeEventListener(
          'click',
          this.handleUploadTriggerClick,
        );
      });
    }

    if (
      this.refs.editorTranscriptUploadLocaleSelect instanceof HTMLSelectElement
    ) {
      this.refs.editorTranscriptUploadLocaleSelect.addEventListener(
        'change',
        this.handleUploadLocaleChange,
      );
      this.disposables.push(() => {
        this.refs.editorTranscriptUploadLocaleSelect?.removeEventListener(
          'change',
          this.handleUploadLocaleChange,
        );
      });
    }

    if (this.refs.editorTranscriptUploadForm instanceof HTMLFormElement) {
      this.refs.editorTranscriptUploadForm.addEventListener(
        'submit',
        this.handleUploadSubmit,
      );
      this.disposables.push(() => {
        this.refs.editorTranscriptUploadForm?.removeEventListener(
          'submit',
          this.handleUploadSubmit,
        );
      });
    }

    if (this.refs.closeEditorTranscriptUploadBtn instanceof HTMLButtonElement) {
      this.refs.closeEditorTranscriptUploadBtn.addEventListener(
        'click',
        this.handleUploadDialogCancel,
      );
      this.disposables.push(() => {
        this.refs.closeEditorTranscriptUploadBtn?.removeEventListener(
          'click',
          this.handleUploadDialogCancel,
        );
      });
    }

    if (
      this.refs.editorTranscriptUploadPermissionInstructionBtn instanceof
      HTMLButtonElement
    ) {
      this.refs.editorTranscriptUploadPermissionInstructionBtn.addEventListener(
        'click',
        this.handleUploadPermissionInstructionClick,
      );
      this.disposables.push(() => {
        this.refs.editorTranscriptUploadPermissionInstructionBtn?.removeEventListener(
          'click',
          this.handleUploadPermissionInstructionClick,
        );
      });
    }

    if (
      this.refs.closeEditorTranscriptUploadPermissionDialogBtn instanceof
      HTMLButtonElement
    ) {
      this.refs.closeEditorTranscriptUploadPermissionDialogBtn.addEventListener(
        'click',
        this.handleUploadPermissionDialogCloseClick,
      );
      this.disposables.push(() => {
        this.refs.closeEditorTranscriptUploadPermissionDialogBtn?.removeEventListener(
          'click',
          this.handleUploadPermissionDialogCloseClick,
        );
      });
    }

    if (this.refs.editorTranscriptUploadDialog instanceof HTMLDialogElement) {
      this.refs.editorTranscriptUploadDialog.addEventListener(
        'close',
        this.handleUploadDialogClose,
      );
      this.disposables.push(() => {
        this.refs.editorTranscriptUploadDialog?.removeEventListener(
          'close',
          this.handleUploadDialogClose,
        );
      });
    }

    this.refs.simpleEditorToggle?.addEventListener(
      'change',
      this.handleHostModeChange,
    );
    this.disposables.push(() => {
      this.refs.simpleEditorToggle?.removeEventListener(
        'change',
        this.handleHostModeChange,
      );
    });

    if (this.refs.editorTranscriptBrowserWarning instanceof HTMLElement) {
      this.refs.editorTranscriptBrowserWarning.addEventListener(
        'pointerenter',
        this.handleBrowserWarningPointerEnter,
      );
      this.refs.editorTranscriptBrowserWarning.addEventListener(
        'pointerleave',
        this.handleBrowserWarningPointerLeave,
      );
      this.disposables.push(() => {
        this.refs.editorTranscriptBrowserWarning?.removeEventListener(
          'pointerenter',
          this.handleBrowserWarningPointerEnter,
        );
        this.refs.editorTranscriptBrowserWarning?.removeEventListener(
          'pointerleave',
          this.handleBrowserWarningPointerLeave,
        );
      });

      if (typeof this.ownerWindow?.ResizeObserver === 'function') {
        this.browserWarningResizeObserver = new this.ownerWindow.ResizeObserver(
          this.handleBrowserWarningResize,
        );
        this.browserWarningResizeObserver.observe(
          this.refs.editorTranscriptBrowserWarning,
        );

        const marquee = this.refs.editorTranscriptBrowserWarning.querySelector(
          '.editor-transcript__warning-marquee',
        );

        if (marquee instanceof HTMLElement) {
          this.browserWarningResizeObserver.observe(marquee);
        }

        this.disposables.push(() => {
          this.browserWarningResizeObserver?.disconnect();
          this.browserWarningResizeObserver = null;
        });
      }

      this.ownerWindow?.addEventListener?.(
        'resize',
        this.handleBrowserWarningResize,
      );
      this.disposables.push(() => {
        this.ownerWindow?.removeEventListener?.(
          'resize',
          this.handleBrowserWarningResize,
        );
      });
    }
  }

  attachEditorListeners() {
    const selectionDisposable = this.editor?.onDidChangeCursorSelection?.(
      (event) => {
        if (!this.isMonacoAvailable()) {
          return;
        }

        this.selection =
          event?.selection || this.editor?.getSelection?.() || null;
      },
    );

    if (selectionDisposable?.dispose) {
      this.disposables.push(() => {
        selectionDisposable.dispose();
      });
    }
  }

  getState() {
    const transcriptSupport = getTranscriptSupportState(this.ownerWindow);

    return {
      audioLevel: this.audioLevel,
      isEnabled: this.isEnabled,
      locale: this.selectedLocale,
      resolvedLocale: this.resolvedLocale,
      supported: transcriptSupport.isSupported,
    };
  }

  destroy() {
    this.destroyed = true;
    this.isEnabled = false;
    this.cancelUploadRequest();
    this.isBrowserWarningHovered = false;
    this.stopRequested = true;
    this.pendingRestart = false;
    this.clearBrowserWarningTimers();
    this.cancelBrowserWarningMarqueeSync();
    this.clearStatusTimer();
    this.stopRecognition(false);
    this.stopAudioMeter();

    if (this.recognition) {
      try {
        this.recognition.stop();
      } catch {
        // NO-OP
      }
    }

    this.disposables.forEach((dispose) => {
      try {
        dispose?.();
      } catch {
        // NO-OP
      }
    });
    this.disposables = [];
    this.lastLocaleOptionsKey = null;
    this.lastUploadLocaleOptionsKey = null;

    if (this.refs.editorTranscriptStatus instanceof HTMLElement) {
      this.refs.editorTranscriptStatus.textContent = '';
    }

    this.closeUploadDialog();
    this.setUploadDialogMessage(TRANSCRIPT_UPLOAD_DEFAULT_MESSAGE);

    this.syncBrowserWarning(false);
    this.disableHostUi('Speech to text unavailable');
    updateStatus();
  }

  syncHostUi() {
    const transcriptSupport = getTranscriptSupportState(this.ownerWindow);
    const localeLabel = this.selectedLocale
      ? `Speech recognition locale: ${this.resolvedLocale}`
      : `Speech recognition locale: Auto (${this.resolvedLocale})`;
    const simpleModeLabel = 'Speech to text is available only in Monaco editor';
    const buttonLabel = this.isEnabled
      ? 'Disable speech to text'
      : 'Enable speech to text';
    const uploadButtonLabel = this.isUploadInFlight
      ? 'Uploading audio for transcription'
      : this.isEnabled
        ? 'Disable speech to text before uploading audio'
        : this.isMonacoAvailable()
          ? 'Upload audio to transcribe'
          : simpleModeLabel;
    const disabledLabel = !transcriptSupport.isDesktopGoogleChrome
      ? TRANSCRIPT_DESKTOP_CHROME_ONLY_LABEL
      : TRANSCRIPT_RECOGNITION_UNAVAILABLE_LABEL;
    const isLiveTranscriptAvailable = transcriptSupport.isSupported;
    const canUseTranscript =
      isLiveTranscriptAvailable && this.isMonacoAvailable();
    const canUseUpload = this.isMonacoAvailable() && !this.isEnabled;

    this.populateLocaleOptions();
    this.populateUploadLocaleOptions();
    this.syncBrowserWarning(
      transcriptSupport.shouldShowBrowserWarning,
      transcriptSupport.shouldShowDownloadChromeWarning,
    );

    if (this.refs.editorTranscriptLocaleSelect instanceof HTMLSelectElement) {
      this.refs.editorTranscriptLocaleSelect.hidden =
        !isLiveTranscriptAvailable;
      this.refs.editorTranscriptLocaleSelect.disabled = !canUseTranscript;
      this.refs.editorTranscriptLocaleSelect.title =
        !transcriptSupport.isSupported
          ? disabledLabel
          : this.isMonacoAvailable()
            ? localeLabel
            : simpleModeLabel;
    }

    if (this.refs.editorTranscriptToggleBtn instanceof HTMLButtonElement) {
      const nextLabel = !transcriptSupport.isSupported
        ? disabledLabel
        : this.isMonacoAvailable()
          ? buttonLabel
          : simpleModeLabel;

      this.refs.editorTranscriptToggleBtn.hidden = !isLiveTranscriptAvailable;
      this.refs.editorTranscriptToggleBtn.disabled = !canUseTranscript;
      this.refs.editorTranscriptToggleBtn.classList.toggle(
        'active',
        this.isEnabled,
      );
      this.refs.editorTranscriptToggleBtn.setAttribute(
        'aria-pressed',
        String(this.isEnabled),
      );
      this.refs.editorTranscriptToggleBtn.setAttribute('aria-label', nextLabel);
      this.refs.editorTranscriptToggleBtn.setAttribute('title', nextLabel);

      const labelNode =
        this.refs.editorTranscriptToggleBtn.querySelector('.visually-hidden');

      if (labelNode instanceof HTMLElement) {
        labelNode.textContent = nextLabel;
      }
    }

    if (this.refs.editorTranscriptUploadBtn instanceof HTMLButtonElement) {
      this.refs.editorTranscriptUploadBtn.disabled = !canUseUpload;
      this.refs.editorTranscriptUploadBtn.setAttribute(
        'aria-label',
        uploadButtonLabel,
      );
      this.refs.editorTranscriptUploadBtn.setAttribute(
        'title',
        uploadButtonLabel,
      );

      const labelNode =
        this.refs.editorTranscriptUploadBtn.querySelector('.visually-hidden');

      if (labelNode instanceof HTMLElement) {
        labelNode.textContent = uploadButtonLabel;
      }
    }

    this.syncUploadDialogUi();

    this.updateMicButtonStyles();
  }

  disableHostUi(label) {
    if (this.refs.editorTranscriptLocaleSelect instanceof HTMLSelectElement) {
      this.refs.editorTranscriptLocaleSelect.disabled = true;
      this.refs.editorTranscriptLocaleSelect.title = label;
    }

    if (this.refs.editorTranscriptToggleBtn instanceof HTMLButtonElement) {
      this.refs.editorTranscriptToggleBtn.disabled = true;
      this.refs.editorTranscriptToggleBtn.classList.remove('active');
      this.refs.editorTranscriptToggleBtn.setAttribute('aria-pressed', 'false');
      this.refs.editorTranscriptToggleBtn.setAttribute('aria-label', label);
      this.refs.editorTranscriptToggleBtn.setAttribute('title', label);

      const labelNode =
        this.refs.editorTranscriptToggleBtn.querySelector('.visually-hidden');

      if (labelNode instanceof HTMLElement) {
        labelNode.textContent = label;
      }

      this.updateMicButtonStyles();
    }

    if (this.refs.editorTranscriptUploadBtn instanceof HTMLButtonElement) {
      this.refs.editorTranscriptUploadBtn.disabled = true;
      this.refs.editorTranscriptUploadBtn.setAttribute('aria-label', label);
      this.refs.editorTranscriptUploadBtn.setAttribute('title', label);

      const labelNode =
        this.refs.editorTranscriptUploadBtn.querySelector('.visually-hidden');

      if (labelNode instanceof HTMLElement) {
        labelNode.textContent = label;
      }
    }
  }

  handleToggleMouseDown(event) {
    event.preventDefault();
  }

  handleToggleClick() {
    const transcriptSupport = getTranscriptSupportState(this.ownerWindow);

    if (!transcriptSupport.isDesktopGoogleChrome) {
      this.announceStatus(TRANSCRIPT_DESKTOP_CHROME_ONLY_STATUS);
      return;
    }

    if (!transcriptSupport.isRecognitionAvailable) {
      this.announceStatus(TRANSCRIPT_RECOGNITION_UNAVAILABLE_LABEL);
      return;
    }

    if (!this.isMonacoAvailable()) {
      this.announceStatus('Speech to text is available only in Monaco editor.');
      return;
    }

    const nextEnabled = !this.isEnabled;

    if (nextEnabled) {
      this.editor?.focus?.();
    }

    this.setEnabled(nextEnabled);
  }

  handleLocaleChange(event) {
    const nextLocale = event?.target?.value;
    this.commitLocale(nextLocale);
  }

  handleUploadLocaleChange(event) {
    const nextLocale = event?.target?.value;
    this.commitLocale(nextLocale || DEFAULT_TRANSCRIPT_LOCALE);
  }

  handleHostModeChange() {
    if (!this.isMonacoAvailable() && this.isEnabled) {
      this.setEnabled(false);
    }

    if (!this.isMonacoAvailable()) {
      this.closeUploadDialog();
    }

    this.syncHostUi();
  }

  handleUploadTriggerClick() {
    if (this.isEnabled) {
      this.announceStatus('Disable speech to text before uploading audio.');
      return;
    }

    if (!this.isMonacoAvailable()) {
      this.announceStatus('Speech to text is available only in Monaco editor.');
      return;
    }

    this.selection = this.editor?.getSelection?.() || this.selection;
    this.openUploadDialog();
  }

  handleUploadDialogCancel() {
    this.closeUploadDialog();
  }

  handleUploadPermissionInstructionClick() {
    this.openUploadPermissionDialog();
  }

  handleUploadPermissionDialogCloseClick() {
    this.closeUploadPermissionDialog();
  }

  handleUploadDialogClose() {
    if (!this.isUploadInFlight) {
      this.setUploadDialogMessage(TRANSCRIPT_UPLOAD_DEFAULT_MESSAGE);
      this.setUploadPermissionTipVisible(false);
    }

    if (
      this.refs.editorTranscriptUploadFileInput instanceof HTMLInputElement &&
      !this.isUploadInFlight
    ) {
      this.refs.editorTranscriptUploadFileInput.value = '';
    }

    this.editor?.focus?.();
  }

  async handleUploadSubmit(event) {
    event.preventDefault();
    this.setUploadPermissionTipVisible(false);

    if (!this.isMonacoAvailable()) {
      this.setUploadDialogMessage(
        'Speech to text is available only in Monaco editor.',
        'error',
      );
      return;
    }

    const file =
      this.refs.editorTranscriptUploadFileInput instanceof HTMLInputElement
        ? this.refs.editorTranscriptUploadFileInput.files?.[0] || null
        : null;
    const apiKey = this.getUploadApiKey();

    if (!file) {
      this.setUploadDialogMessage(
        TRANSCRIPT_UPLOAD_EMPTY_FILE_MESSAGE,
        'error',
      );
      return;
    }

    if (!apiKey) {
      this.setUploadDialogMessage(
        TRANSCRIPT_UPLOAD_EMPTY_API_KEY_MESSAGE,
        'error',
      );
      this.refs.editorTranscriptUploadApiKeyInput?.focus?.();
      return;
    }

    const requestLocale =
      normalizeTranscriptLocale(
        this.refs.editorTranscriptUploadLocaleSelect instanceof
          HTMLSelectElement
          ? this.refs.editorTranscriptUploadLocaleSelect.value
          : this.selectedLocale,
      ) || DEFAULT_TRANSCRIPT_LOCALE;

    this.selection = this.editor?.getSelection?.() || this.selection;
    this.commitLocale(requestLocale);
    this.preferences.saveTranscriptUploadApiKeyPreference(apiKey);
    this.setUploadBusyState(true);
    this.setUploadDialogMessage(TRANSCRIPT_UPLOAD_IN_PROGRESS_MESSAGE);
    this.setUploadPermissionTipVisible(false);

    const formData = new FormData();
    formData.append('model_id', TRANSCRIPT_UPLOAD_MODEL_ID);
    formData.append('file', file);
    formData.append('language_code', this.getUploadLanguageCode(requestLocale));

    this.uploadAbortController = new AbortController();

    try {
      const response = await fetch(TRANSCRIPT_UPLOAD_ENDPOINT, {
        body: formData,
        headers: {
          'xi-api-key': apiKey,
        },
        method: 'POST',
        signal: this.uploadAbortController.signal,
      });
      const payload = await this.readUploadResponsePayload(response);

      if (!response.ok) {
        const uploadError = new Error(
          this.getUploadResponseErrorMessage(response, payload),
        );

        uploadError.shouldShowPermissionTip = response.status === 401;

        throw uploadError;
      }

      const transcript = String(
        payload?.text ?? payload?.transcript ?? payload?.result ?? '',
      ).trim();

      if (!transcript) {
        throw new Error(TRANSCRIPT_UPLOAD_EMPTY_TRANSCRIPT_MESSAGE);
      }

      const committedTranscript = await this.getCommittedTranscript(
        transcript,
        null,
      );
      const range = this.getActiveEditRange();

      if (!range) {
        throw new Error(
          'Editor selection is unavailable for transcript insertion.',
        );
      }

      this.replaceRange(
        range,
        committedTranscript,
        'open-lyric-transcript-upload',
      );
      this.closeUploadDialog('submit');
      this.announceStatus(TRANSCRIPT_UPLOAD_SUCCESS_MESSAGE);
    } catch (error) {
      this.setUploadPermissionTipVisible(
        Boolean(error?.shouldShowPermissionTip),
      );

      if (error?.name === 'AbortError') {
        this.setUploadDialogMessage('Audio transcription cancelled.');
      } else {
        this.setUploadDialogMessage(
          error instanceof Error
            ? error.message
            : 'Failed to transcribe audio.',
          'error',
        );
      }
    } finally {
      this.uploadAbortController = null;
      this.setUploadBusyState(false);
      this.syncHostUi();
    }
  }

  handleBrowserWarningPointerEnter() {
    this.isBrowserWarningHovered = true;
    this.clearBrowserWarningTimers();

    if (this.refs.editorTranscriptBrowserWarning instanceof HTMLElement) {
      this.refs.editorTranscriptBrowserWarning.classList.remove(
        'editor-transcript__warning--fading',
      );
    }
  }

  handleBrowserWarningPointerLeave() {
    this.isBrowserWarningHovered = false;

    if (
      this.refs.editorTranscriptBrowserWarning instanceof HTMLElement &&
      !this.refs.editorTranscriptBrowserWarning.hidden
    ) {
      this.scheduleBrowserWarningDismissal();
    }
  }

  handleBrowserWarningResize() {
    this.scheduleBrowserWarningMarqueeSync();
  }

  commitLocale(nextLocale) {
    const normalizedLocale = normalizeTranscriptLocale(nextLocale);
    this.selectedLocale = normalizedLocale;
    this.resolvedLocale = resolveTranscriptLocale(normalizedLocale);
    this.preferences.saveTranscriptLocalePreference(normalizedLocale);
    this.syncHostUi();

    if (this.recognition) {
      this.recognition.lang = this.resolvedLocale;
    }

    if (this.isEnabled) {
      if (
        this.recognitionLifecycle === 'active' ||
        this.recognitionLifecycle === 'starting'
      ) {
        this.stopRecognition(true);
      } else if (this.recognitionLifecycle === 'inactive') {
        this.startRecognition();
      }
    }

    this.onStateChange?.(this.getState());
  }

  openUploadDialog() {
    if (
      !(this.refs.editorTranscriptUploadDialog instanceof HTMLDialogElement)
    ) {
      return;
    }

    this.populateUploadLocaleOptions();
    if (
      this.refs.editorTranscriptUploadApiKeyInput instanceof HTMLInputElement
    ) {
      this.refs.editorTranscriptUploadApiKeyInput.value =
        this.preferences.loadTranscriptUploadApiKeyPreference('');
    }
    this.setUploadDialogMessage(TRANSCRIPT_UPLOAD_DEFAULT_MESSAGE);
    this.setUploadPermissionTipVisible(false);

    if (!this.refs.editorTranscriptUploadDialog.open) {
      this.refs.editorTranscriptUploadDialog.showModal();
    }
  }

  closeUploadDialog(returnValue = 'cancel') {
    if (
      !(this.refs.editorTranscriptUploadDialog instanceof HTMLDialogElement) ||
      !this.refs.editorTranscriptUploadDialog.open
    ) {
      return;
    }

    this.refs.editorTranscriptUploadDialog.close(returnValue);
  }

  openUploadPermissionDialog() {
    if (
      !(
        this.refs.editorTranscriptUploadPermissionDialog instanceof
        HTMLDialogElement
      )
    ) {
      return;
    }

    if (!this.refs.editorTranscriptUploadPermissionDialog.open) {
      this.refs.editorTranscriptUploadPermissionDialog.showModal();
    }
  }

  closeUploadPermissionDialog() {
    if (
      !(
        this.refs.editorTranscriptUploadPermissionDialog instanceof
        HTMLDialogElement
      ) ||
      !this.refs.editorTranscriptUploadPermissionDialog.open
    ) {
      return;
    }

    this.refs.editorTranscriptUploadPermissionDialog.close();
  }

  cancelUploadRequest() {
    this.uploadAbortController?.abort?.();
    this.uploadAbortController = null;
    this.isUploadInFlight = false;
  }

  setUploadBusyState(isBusy) {
    const nextBusyState = Boolean(isBusy);

    this.isUploadInFlight = nextBusyState;

    if (this.refs.editorTranscriptUploadFileInput instanceof HTMLInputElement) {
      this.refs.editorTranscriptUploadFileInput.disabled = nextBusyState;
    }

    if (
      this.refs.editorTranscriptUploadApiKeyInput instanceof HTMLInputElement
    ) {
      this.refs.editorTranscriptUploadApiKeyInput.disabled = nextBusyState;
    }

    if (
      this.refs.editorTranscriptUploadLocaleSelect instanceof HTMLSelectElement
    ) {
      this.refs.editorTranscriptUploadLocaleSelect.disabled = nextBusyState;
    }

    if (this.refs.closeEditorTranscriptUploadBtn instanceof HTMLButtonElement) {
      this.refs.closeEditorTranscriptUploadBtn.disabled = nextBusyState;
    }

    if (
      this.refs.submitEditorTranscriptUploadBtn instanceof HTMLButtonElement
    ) {
      this.refs.submitEditorTranscriptUploadBtn.disabled = nextBusyState;
      this.refs.submitEditorTranscriptUploadBtn.textContent = nextBusyState
        ? 'Transcribing...'
        : 'Transcribe Audio';
    }
  }

  syncUploadDialogUi() {
    const localeValue = this.getUploadLocaleValue();
    const canUseUpload = this.isMonacoAvailable() && !this.isEnabled;

    if (
      this.refs.editorTranscriptUploadLocaleSelect instanceof
        HTMLSelectElement &&
      !this.isUploadInFlight
    ) {
      this.refs.editorTranscriptUploadLocaleSelect.disabled = !canUseUpload;
      this.refs.editorTranscriptUploadLocaleSelect.value = localeValue;
    }

    if (
      this.refs.editorTranscriptUploadFileInput instanceof HTMLInputElement &&
      !this.isUploadInFlight
    ) {
      this.refs.editorTranscriptUploadFileInput.disabled = !canUseUpload;
    }

    if (
      this.refs.editorTranscriptUploadApiKeyInput instanceof HTMLInputElement &&
      !this.isUploadInFlight
    ) {
      this.refs.editorTranscriptUploadApiKeyInput.disabled = !canUseUpload;
    }

    if (
      this.refs.submitEditorTranscriptUploadBtn instanceof HTMLButtonElement &&
      !this.isUploadInFlight
    ) {
      this.refs.submitEditorTranscriptUploadBtn.disabled = !canUseUpload;
    }
  }

  setUploadDialogMessage(message, tone = 'muted') {
    if (!(this.refs.editorTranscriptUploadMessage instanceof HTMLElement)) {
      return;
    }

    this.refs.editorTranscriptUploadMessage.dataset.tone = tone;
    this.refs.editorTranscriptUploadMessage.textContent = message;
  }

  setUploadPermissionTipVisible(isVisible) {
    if (
      !(this.refs.editorTranscriptUploadPermissionTip instanceof HTMLElement)
    ) {
      return;
    }

    this.refs.editorTranscriptUploadPermissionTip.hidden = !isVisible;
  }

  async readUploadResponsePayload(response) {
    const contentType = String(response.headers.get('content-type') || '');

    if (contentType.includes('application/json')) {
      return response.json().catch(() => null);
    }

    const text = await response.text().catch(() => '');

    if (!text) {
      return null;
    }

    return {
      error: text,
      text,
    };
  }

  getUploadResponseErrorMessage(response, payload) {
    const payloadMessage = this.getUploadPayloadErrorMessage(payload);

    if (response.status === 401) {
      return payloadMessage
        ? `ElevenLabs rejected the API key: ${payloadMessage}`
        : TRANSCRIPT_UPLOAD_UNAUTHORIZED_MESSAGE;
    }

    return payloadMessage || 'Failed to transcribe audio.';
  }

  getUploadPayloadErrorMessage(payload) {
    if (!payload) {
      return '';
    }

    if (typeof payload === 'string') {
      return payload.trim();
    }

    if (typeof payload !== 'object') {
      return '';
    }

    return this.normalizeUploadErrorMessage(
      payload.error ?? payload.message ?? payload.detail,
    );
  }

  normalizeUploadErrorMessage(value) {
    if (!value) {
      return '';
    }

    if (typeof value === 'string') {
      return value.trim();
    }

    if (Array.isArray(value)) {
      return value
        .map((entry) => this.normalizeUploadErrorMessage(entry))
        .filter(Boolean)
        .join('; ');
    }

    if (typeof value === 'object') {
      return this.normalizeUploadErrorMessage(
        value.message ?? value.error ?? value.reason ?? value.status,
      );
    }

    return String(value).trim();
  }

  setEnabled(enabled) {
    this.isEnabled = Boolean(enabled);
    this.stopRequested = !this.isEnabled;

    if (!this.isEnabled) {
      this.interimRange = null;
      this.processedFinalResults.clear();
      this.updateAudioLevel(0);
      this.stopAudioMeter();
      this.stopRecognition(false);
    } else {
      this.startRecognition();
      void this.startAudioMeter();
    }

    this.syncHostUi();
    this.onStateChange?.(this.getState());
  }

  syncBrowserWarning(shouldShow, shouldShowDownloadChromeWarning) {
    if (this.refs.editorTranscriptBrowserWarning instanceof HTMLElement) {
      this.refs.editorTranscriptBrowserWarning.dataset.showDownloadLink =
        shouldShowDownloadChromeWarning ? 'true' : 'false';

      if (shouldShow) {
        const wasHidden = this.refs.editorTranscriptBrowserWarning.hidden;

        this.refs.editorTranscriptBrowserWarning.hidden = false;

        if (wasHidden) {
          this.refs.editorTranscriptBrowserWarning.classList.remove(
            'editor-transcript__warning--fading',
          );
          this.scheduleBrowserWarningDismissal();
        }

        this.scheduleBrowserWarningMarqueeSync();
      } else {
        this.isBrowserWarningHovered = false;
        this.clearBrowserWarningTimers();
        this.cancelBrowserWarningMarqueeSync();
        this.refs.editorTranscriptBrowserWarning.hidden = true;
        this.refs.editorTranscriptBrowserWarning.classList.remove(
          'editor-transcript__warning--fading',
        );
        this.refs.editorTranscriptBrowserWarning.classList.remove(
          'editor-transcript__warning--overflowing',
        );
      }
    }

    if (
      this.refs.editorTranscriptDownloadChromeWarning instanceof HTMLElement
    ) {
      this.refs.editorTranscriptDownloadChromeWarning.hidden =
        !shouldShowDownloadChromeWarning;
    }
  }

  scheduleBrowserWarningMarqueeSync() {
    if (this.browserWarningMarqueeFrame) {
      return;
    }

    if (typeof this.ownerWindow?.requestAnimationFrame !== 'function') {
      this.syncBrowserWarningMarqueeOverflow();
      return;
    }

    this.browserWarningMarqueeFrame = this.ownerWindow.requestAnimationFrame(
      () => {
        this.browserWarningMarqueeFrame = 0;
        this.syncBrowserWarningMarqueeOverflow();
      },
    );
  }

  cancelBrowserWarningMarqueeSync() {
    if (!this.browserWarningMarqueeFrame) {
      return;
    }

    if (typeof this.ownerWindow?.cancelAnimationFrame === 'function') {
      this.ownerWindow.cancelAnimationFrame(this.browserWarningMarqueeFrame);
    }

    this.browserWarningMarqueeFrame = 0;
  }

  syncBrowserWarningMarqueeOverflow() {
    const warning = this.refs.editorTranscriptBrowserWarning;

    if (!(warning instanceof HTMLElement)) {
      return;
    }

    if (warning.hidden) {
      warning.classList.remove('editor-transcript__warning--overflowing');
      return;
    }

    const marquee = warning.querySelector(
      '.editor-transcript__warning-marquee',
    );
    const segment = warning.querySelector(
      '.editor-transcript__warning-segment:not(.editor-transcript__warning-segment--clone)',
    );

    if (
      !(marquee instanceof HTMLElement) ||
      !(segment instanceof HTMLElement)
    ) {
      warning.classList.remove('editor-transcript__warning--overflowing');
      return;
    }

    const availableWidth = marquee.clientWidth;
    const segmentWidth = segment.getBoundingClientRect().width;
    const isOverflowing =
      availableWidth > 0 && segmentWidth > availableWidth + 1;

    warning.classList.toggle(
      'editor-transcript__warning--overflowing',
      isOverflowing,
    );
  }

  clearBrowserWarningTimers() {
    if (this.browserWarningHideTimer) {
      this.ownerWindow.clearTimeout(this.browserWarningHideTimer);
      this.browserWarningHideTimer = 0;
    }

    if (this.browserWarningFadeTimer) {
      this.ownerWindow.clearTimeout(this.browserWarningFadeTimer);
      this.browserWarningFadeTimer = 0;
    }
  }

  scheduleBrowserWarningDismissal() {
    if (
      !(this.refs.editorTranscriptBrowserWarning instanceof HTMLElement) ||
      this.isBrowserWarningHovered
    ) {
      return;
    }

    this.clearBrowserWarningTimers();
    this.browserWarningHideTimer = this.ownerWindow.setTimeout(() => {
      this.browserWarningHideTimer = 0;

      if (!(this.refs.editorTranscriptBrowserWarning instanceof HTMLElement)) {
        return;
      }

      if (this.isBrowserWarningHovered) {
        return;
      }

      this.refs.editorTranscriptBrowserWarning.classList.add(
        'editor-transcript__warning--fading',
      );
      this.browserWarningFadeTimer = this.ownerWindow.setTimeout(() => {
        this.browserWarningFadeTimer = 0;

        if (
          !(this.refs.editorTranscriptBrowserWarning instanceof HTMLElement)
        ) {
          return;
        }

        if (this.isBrowserWarningHovered) {
          this.refs.editorTranscriptBrowserWarning.classList.remove(
            'editor-transcript__warning--fading',
          );
          return;
        }

        this.refs.editorTranscriptBrowserWarning.hidden = true;
        this.refs.editorTranscriptBrowserWarning.classList.remove(
          'editor-transcript__warning--fading',
        );
      }, TRANSCRIPT_BROWSER_WARNING_FADE_DURATION_MS);
    }, TRANSCRIPT_BROWSER_WARNING_VISIBLE_DURATION_MS);
  }

  ensureRecognition() {
    if (!SUPPORT_TRANSCRIPT_RECOGNITION || this.recognition) {
      return this.recognition;
    }

    const SpeechRecognitionConstructor =
      window.SpeechRecognition || window.webkitSpeechRecognition;

    if (typeof SpeechRecognitionConstructor !== 'function') {
      return null;
    }

    this.recognition = new SpeechRecognitionConstructor();
    this.recognition.continuous = true;
    this.recognition.interimResults = true;
    this.recognition.lang = this.resolvedLocale;
    this.recognition.addEventListener('start', () => {
      this.recognitionLifecycle = 'active';
      this.processedFinalResults.clear();
      this.stopRequested = false;
    });
    this.recognition.addEventListener('end', () => {
      const shouldRestart =
        this.isEnabled && (this.pendingRestart || !this.stopRequested);

      this.recognitionLifecycle = 'inactive';
      this.pendingRestart = false;

      if (shouldRestart) {
        this.startRecognition();
      }
    });
    this.recognition.addEventListener('error', (event) => {
      const error = event?.error ?? 'unknown';
      const message =
        error === 'network'
          ? 'Speech recognition failed with a network error. Use Google Chrome on desktop with internet access and without privacy tools blocking speech requests.'
          : `Speech recognition failed: ${error}.`;

      this.stopRequested = true;
      this.pendingRestart = false;
      this.recognitionLifecycle = 'inactive';
      this.isEnabled = false;
      this.interimRange = null;
      this.processedFinalResults.clear();
      this.stopAudioMeter();
      this.syncHostUi();
      this.announceStatus(message);
      this.onStateChange?.(this.getState());
    });
    this.recognition.addEventListener('result', (event) => {
      const resultIndex = event.resultIndex;
      const resultItem = event.results.item(event.resultIndex);
      const transcript = resultItem?.item(0)?.transcript ?? '';

      if (resultItem?.isFinal) {
        const processedTranscript = this.processedFinalResults.get(resultIndex);

        if (processedTranscript === transcript) {
          return;
        }

        this.processedFinalResults.set(resultIndex, transcript);
      } else {
        this.processedFinalResults.delete(resultIndex);
      }

      if (resultItem?.isFinal) {
        void this.queueFinalizeTranscript(transcript);
      } else {
        this.updateInterimTranscript(transcript);
      }
    });

    return this.recognition;
  }

  startRecognition() {
    const recognition = this.ensureRecognition();

    if (!recognition) {
      return;
    }

    if (
      this.recognitionLifecycle === 'active' ||
      this.recognitionLifecycle === 'starting'
    ) {
      return;
    }

    recognition.lang = this.resolvedLocale;
    this.recognitionLifecycle = 'starting';

    try {
      recognition.start();
    } catch {
      this.recognitionLifecycle = 'inactive';
    }
  }

  stopRecognition(shouldRestart) {
    if (!this.recognition) {
      return;
    }

    this.pendingRestart = Boolean(shouldRestart);
    this.stopRequested = !shouldRestart;

    if (this.recognitionLifecycle === 'inactive') {
      if (shouldRestart && this.isEnabled) {
        this.startRecognition();
      }

      return;
    }

    if (this.recognitionLifecycle === 'stopping') {
      return;
    }

    this.recognitionLifecycle = 'stopping';

    try {
      this.recognition.stop();
    } catch {
      this.recognitionLifecycle = 'inactive';
    }
  }

  async startAudioMeter() {
    const AudioContextConstructor =
      window.AudioContext || window.webkitAudioContext;

    if (
      this.audioContext ||
      typeof AudioContextConstructor !== 'function' ||
      navigator.mediaDevices?.getUserMedia == null
    ) {
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          autoGainControl: true,
          echoCancellation: true,
          noiseSuppression: true,
        },
      });

      if (!this.isEnabled) {
        stream.getTracks().forEach((track) => track.stop());
        return;
      }

      const audioContext = new AudioContextConstructor();
      const source = audioContext.createMediaStreamSource(stream);
      const analyser = audioContext.createAnalyser();

      analyser.fftSize = AUDIO_FFT_SIZE;
      analyser.smoothingTimeConstant = 0.82;
      source.connect(analyser);

      this.audioContext = audioContext;
      this.audioSource = source;
      this.analyser = analyser;
      this.audioStream = stream;
      this.frequencyData = new Uint8Array(analyser.frequencyBinCount);
      this.updateAudioLevel(0);
      this.meterFrame = this.ownerWindow.requestAnimationFrame(
        this.measureAudioLevel,
      );
    } catch {
      this.stopAudioMeter();
    }
  }

  stopAudioMeter() {
    if (this.meterFrame) {
      this.ownerWindow.cancelAnimationFrame(this.meterFrame);
      this.meterFrame = 0;
    }

    this.analyser?.disconnect?.();
    this.analyser = null;

    this.audioSource?.disconnect?.();
    this.audioSource = null;

    this.audioStream?.getTracks?.().forEach((track) => track.stop());
    this.audioStream = null;

    this.frequencyData = null;

    if (this.audioContext) {
      void this.audioContext.close().catch(() => {
        // NO-OP
      });
      this.audioContext = null;
    }

    this.updateAudioLevel(0);
  }

  measureAudioLevel() {
    if (!this.analyser || !this.frequencyData || !this.isEnabled) {
      this.meterFrame = 0;
      return;
    }

    this.analyser.getByteFrequencyData(this.frequencyData);

    let average = 0;
    let peak = 0;

    for (const value of this.frequencyData) {
      average += value;
      peak = Math.max(peak, value);
    }

    average /= this.frequencyData.length;

    const normalizedAverage = Math.max(0, (average - 10) / 72);
    const normalizedPeak = Math.max(0, (peak - 24) / 144);
    const level = Math.min(1, normalizedAverage * 0.65 + normalizedPeak * 0.55);
    const smoothedLevel =
      level < 0.035 ? 0 : this.audioLevel * 0.45 + level * 0.55;

    this.updateAudioLevel(Math.min(1, smoothedLevel));
    this.meterFrame = this.ownerWindow.requestAnimationFrame(
      this.measureAudioLevel,
    );
  }

  updateAudioLevel(audioLevel) {
    const roundedAudioLevel = Number(audioLevel.toFixed(3));

    if (
      Math.abs(roundedAudioLevel - this.audioLevel) < AUDIO_LEVEL_EPSILON &&
      !(roundedAudioLevel === 0 && this.audioLevel !== 0)
    ) {
      return;
    }

    this.audioLevel = roundedAudioLevel;
    this.updateMicButtonStyles();
    this.onStateChange?.(this.getState());
  }

  updateMicButtonStyles() {
    if (!(this.refs.editorTranscriptToggleBtn instanceof HTMLButtonElement)) {
      return;
    }

    if (!this.isEnabled) {
      this.refs.editorTranscriptToggleBtn.style.removeProperty(
        '--mic-input-level',
      );
      this.refs.editorTranscriptToggleBtn.style.removeProperty(
        '--mic-ring-opacity',
      );
      this.refs.editorTranscriptToggleBtn.style.removeProperty(
        '--mic-ring-scale',
      );
      return;
    }

    this.refs.editorTranscriptToggleBtn.style.setProperty(
      '--mic-input-level',
      this.audioLevel.toFixed(3),
    );
    this.refs.editorTranscriptToggleBtn.style.setProperty(
      '--mic-ring-opacity',
      `${Math.min(0.9, this.audioLevel * 1.15).toFixed(3)}`,
    );
    this.refs.editorTranscriptToggleBtn.style.setProperty(
      '--mic-ring-scale',
      `${(1 + this.audioLevel * 0.85).toFixed(3)}`,
    );
  }

  updateInterimTranscript(transcript) {
    if (!this.isMonacoAvailable() || transcript.trim().length === 0) {
      return;
    }

    const targetRange = this.getActiveEditRange();

    if (!targetRange) {
      return;
    }

    this.interimRange = this.replaceRange(
      targetRange,
      transcript,
      'open-lyric-transcript-interim',
    );
  }

  queueFinalizeTranscript(transcript) {
    const nextTranscript = String(transcript || '');

    this.finalizationPromise = this.finalizationPromise
      .catch(() => {
        // NO-OP
      })
      .then(() => this.finalizeTranscript(nextTranscript))
      .catch((error) => {
        console.error('Failed to finalize transcript.', error);
      });

    return this.finalizationPromise;
  }

  async getCommittedTranscript(transcript, command) {
    if (command || !transcript) {
      return transcript;
    }

    return postProcessTranscriptText(this.resolvedLocale, transcript);
  }

  async finalizeTranscript(transcript) {
    if (!this.isMonacoAvailable()) {
      return;
    }

    const normalizedTranscript = String(transcript || '');
    const command = this.getVoiceCommand(normalizedTranscript);
    const isParagraphTranscript = /\s*\n\s*/.test(normalizedTranscript);
    const committedTranscript = await this.getCommittedTranscript(
      normalizedTranscript,
      command,
    );

    if (this.destroyed || !this.isMonacoAvailable()) {
      return;
    }

    if (this.interimRange) {
      if (!command && !isParagraphTranscript) {
        this.interimRange = this.replaceRange(
          this.interimRange,
          committedTranscript,
          'open-lyric-transcript-final',
        );
        this.interimRange = null;
        return;
      }

      const rangeStart = this.interimRange.getStartPosition();
      this.replaceRange(
        this.interimRange,
        '',
        'open-lyric-transcript-clear-interim',
        { preserveSelectionAtStart: true },
      );
      this.interimRange = null;
      this.selection = new this.monaco.Selection(
        rangeStart.lineNumber,
        rangeStart.column,
        rangeStart.lineNumber,
        rangeStart.column,
      );
      this.editor?.setSelection?.(this.selection);
    }

    if (command === 'undo' || command === 'redo') {
      this.application.runEditorHistoryCommand(command);
      return;
    }

    if (command === 'newline' || isParagraphTranscript) {
      const range = this.getActiveEditRange();

      if (range) {
        this.replaceRange(range, '\n', 'open-lyric-transcript-newline');
      }
      return;
    }

    const range = this.getActiveEditRange();

    if (range) {
      this.replaceRange(range, committedTranscript, 'open-lyric-transcript');
    }
  }

  getVoiceCommand(transcript) {
    const normalizedTranscript = String(transcript || '')
      .toLowerCase()
      .trim();

    if (normalizedTranscript === 'undo') {
      return 'undo';
    }

    if (normalizedTranscript === 'redo') {
      return 'redo';
    }

    if (normalizedTranscript === '\\n') {
      return 'newline';
    }

    return null;
  }

  getModel() {
    return this.editor?.getModel?.() || null;
  }

  getActiveEditRange() {
    if (!this.monaco?.Range) {
      return null;
    }

    if (this.interimRange) {
      return this.interimRange;
    }

    const selection = this.editor?.getSelection?.() || this.selection;

    if (selection) {
      return new this.monaco.Range(
        selection.startLineNumber,
        selection.startColumn,
        selection.endLineNumber,
        selection.endColumn,
      );
    }

    const model = this.getModel();

    if (!model) {
      return null;
    }

    const fullRange = model.getFullModelRange();

    return new this.monaco.Range(
      fullRange.endLineNumber,
      fullRange.endColumn,
      fullRange.endLineNumber,
      fullRange.endColumn,
    );
  }

  replaceRange(range, text, source, { preserveSelectionAtStart = false } = {}) {
    const model = this.getModel();

    if (!model || !this.monaco?.Range || !this.monaco?.Selection || !range) {
      return null;
    }

    const startPosition = range.getStartPosition();
    const startOffset = model.getOffsetAt(startPosition);

    this.editor?.executeEdits?.(source, [
      {
        forceMoveMarkers: true,
        range,
        text,
      },
    ]);

    const endPosition = model.getPositionAt(startOffset + text.length);
    const nextRange = new this.monaco.Range(
      startPosition.lineNumber,
      startPosition.column,
      endPosition.lineNumber,
      endPosition.column,
    );
    const nextSelection = preserveSelectionAtStart
      ? new this.monaco.Selection(
          startPosition.lineNumber,
          startPosition.column,
          startPosition.lineNumber,
          startPosition.column,
        )
      : new this.monaco.Selection(
          endPosition.lineNumber,
          endPosition.column,
          endPosition.lineNumber,
          endPosition.column,
        );

    this.selection = nextSelection;
    this.editor?.setSelection?.(nextSelection);
    this.editor?.revealPositionInCenterIfOutsideViewport?.(
      preserveSelectionAtStart ? startPosition : endPosition,
    );

    return nextRange;
  }

  getTranscriptLocaleOptions(selectedLocale = this.selectedLocale) {
    const localeOptions =
      selectedLocale.length > 0 &&
      !TRANSCRIPT_LOCALE_SUGGESTIONS.includes(selectedLocale)
        ? [selectedLocale, ...TRANSCRIPT_LOCALE_SUGGESTIONS]
        : TRANSCRIPT_LOCALE_SUGGESTIONS;

    return localeOptions;
  }

  populateLocaleOptions() {
    const select = this.refs.editorTranscriptLocaleSelect;

    if (!(select instanceof HTMLSelectElement)) {
      return;
    }

    // The option list only depends on selectedLocale (which options exist) and
    // resolvedLocale (the "Auto (…)" label). syncHostUi runs on every audio
    // frame while recording, so skip the ~215-node rebuild when neither changed.
    const optionsKey = `${this.selectedLocale}�${this.resolvedLocale}`;
    if (this.lastLocaleOptionsKey === optionsKey && select.options.length > 0) {
      select.value = this.selectedLocale;
      if (select.value !== this.selectedLocale) {
        select.value = AUTO_TRANSCRIPT_LOCALE;
      }
      return;
    }

    const localeOptions = this.getTranscriptLocaleOptions();
    select.replaceChildren();

    const autoOption = document.createElement('option');
    autoOption.value = AUTO_TRANSCRIPT_LOCALE;
    autoOption.textContent = `Auto (${this.resolvedLocale})`;
    select.append(autoOption);

    localeOptions.forEach((locale) => {
      const option = document.createElement('option');
      option.value = locale;
      option.textContent = locale;
      select.append(option);
    });

    select.value = this.selectedLocale;

    if (select.value !== this.selectedLocale) {
      select.value = AUTO_TRANSCRIPT_LOCALE;
    }

    this.lastLocaleOptionsKey = optionsKey;
  }

  getUploadLocaleValue() {
    return this.selectedLocale || DEFAULT_TRANSCRIPT_LOCALE;
  }

  getUploadApiKey() {
    if (
      this.refs.editorTranscriptUploadApiKeyInput instanceof HTMLInputElement
    ) {
      return this.refs.editorTranscriptUploadApiKeyInput.value.trim();
    }

    return this.preferences.loadTranscriptUploadApiKeyPreference('');
  }

  getUploadLanguageCode(localeValue) {
    const normalizedLocale = normalizeTranscriptLocale(localeValue);
    const primaryCode = normalizedLocale.split(/[-_]/u, 1)[0]?.toLowerCase();

    return (
      TRANSCRIPT_UPLOAD_LANGUAGE_CODE_ALIASES.get(primaryCode) ||
      primaryCode ||
      'km'
    );
  }

  populateUploadLocaleOptions() {
    const select = this.refs.editorTranscriptUploadLocaleSelect;

    if (!(select instanceof HTMLSelectElement)) {
      return;
    }

    const localeValue = this.getUploadLocaleValue();

    if (
      this.lastUploadLocaleOptionsKey === localeValue &&
      select.options.length > 0
    ) {
      select.value = localeValue;
      if (select.value !== localeValue) {
        select.value = DEFAULT_TRANSCRIPT_LOCALE;
      }
      return;
    }

    const localeOptions = this.getTranscriptLocaleOptions(localeValue);

    select.replaceChildren();

    localeOptions.forEach((locale) => {
      const option = document.createElement('option');
      option.value = locale;
      option.textContent = locale;
      select.append(option);
    });

    select.value = localeValue;

    if (select.value !== localeValue) {
      select.value = DEFAULT_TRANSCRIPT_LOCALE;
    }

    this.lastUploadLocaleOptionsKey = localeValue;
  }

  announceStatus(message) {
    if (this.refs.editorTranscriptStatus instanceof HTMLElement) {
      this.refs.editorTranscriptStatus.textContent = message;
    }

    setStatus(message);
    this.clearStatusTimer();
    this.statusResetTimer = this.ownerWindow.setTimeout(() => {
      this.statusResetTimer = 0;
      updateStatus();
    }, STATUS_RESET_DELAY_MS);
  }

  clearStatusTimer() {
    if (!this.statusResetTimer) {
      return;
    }

    this.ownerWindow.clearTimeout(this.statusResetTimer);
    this.statusResetTimer = 0;
  }

  isMonacoAvailable() {
    return Boolean(this.state?.editorMode === 'monaco' && this.editor);
  }
}

function createTranscriptController(context) {
  return new TranscriptController(context);
}

export { createTranscriptController };
