import {
  createKhmerNidaKeyboard,
  createMonacoInputAdapter,
} from './keyboard-km-nida.ts';
import { EDITOR_ONLY_SHELL_MODE } from '../../scripts/page-config.ts';

const KEYBOARD_CONTEXT_KEY = 'openLyricKhmerNidaKeyboardVisible';
const AUTO_SUGGEST_STORAGE_KEY = 'open-lyric-editor-auto-suggest';
const KEYBOARD_PREFERENCE_ID = 'km-kh-nida-keyboard';

function isEditorOnlyAutoSuggestEnabled(ownerDocument) {
  const documentElement = ownerDocument?.documentElement;

  if (
    !(documentElement instanceof HTMLElement) ||
    documentElement.dataset.editorShell !== EDITOR_ONLY_SHELL_MODE
  ) {
    return false;
  }

  try {
    return (
      ownerDocument.defaultView?.localStorage?.getItem(
        AUTO_SUGGEST_STORAGE_KEY,
      ) !== '0'
    );
  } catch (_error) {
    return true;
  }
}

function createWindowButton(ownerDocument, id, label, ariaLabel) {
  const button = ownerDocument.createElement('button');
  button.className = 'window-button';
  button.id = id;
  button.type = 'button';
  button.textContent = label;
  button.setAttribute('aria-label', ariaLabel);
  return button;
}

function createNavigationButton(
  ownerDocument,
  instanceId,
  direction,
  label,
  ariaLabel,
) {
  const button = ownerDocument.createElement('button');
  button.className = 'keyboard-navigation-button';
  button.id = `khmer-keyboard-nav-${direction}-${instanceId}`;
  button.type = 'button';
  button.dataset.direction = direction;
  button.textContent = label;
  button.setAttribute('aria-label', ariaLabel);
  button.setAttribute('title', ariaLabel);
  return button;
}

function createLayoutOption(
  ownerDocument,
  instanceId,
  layoutId,
  label,
  ariaLabel,
) {
  const button = ownerDocument.createElement('button');
  button.className = 'keyboard-layout-option';
  button.id = `keyboard-layout-option-${layoutId}-${instanceId}`;
  button.type = 'button';
  button.dataset.layoutId = layoutId;
  button.textContent = label;
  button.setAttribute('aria-checked', 'false');
  button.setAttribute('aria-label', ariaLabel);
  button.setAttribute('role', 'menuitemradio');
  return button;
}

function createKhmerKeyboardElements(ownerDocument, instanceId) {
  const keyboard = ownerDocument.createElement('section');
  keyboard.className = 'keyboard-popover ol-editor-khmer-keyboard';
  keyboard.hidden = true;
  keyboard.id = `khmer-keyboard-${instanceId}`;

  const keyboardHeader = ownerDocument.createElement('div');
  keyboardHeader.className = 'keyboard-header';

  const closeButton = createWindowButton(
    ownerDocument,
    `close-khmer-keyboard-${instanceId}`,
    '✕',
    'Close keyboard',
  );
  const keyboardTitle = ownerDocument.createElement('div');
  keyboardTitle.className = 'keyboard-title';
  const keyboardTitleText = ownerDocument.createElement('strong');
  keyboardTitleText.lang = 'km';
  keyboardTitleText.textContent = 'អក្សរខ្មែរ NiDA';
  const navigationButtons = {
    up: createNavigationButton(
      ownerDocument,
      instanceId,
      'up',
      '↑',
      'Move cursor up',
    ),
    left: createNavigationButton(
      ownerDocument,
      instanceId,
      'left',
      '←',
      'Move cursor left',
    ),
    down: createNavigationButton(
      ownerDocument,
      instanceId,
      'down',
      '↓',
      'Move cursor down',
    ),
    right: createNavigationButton(
      ownerDocument,
      instanceId,
      'right',
      '→',
      'Move cursor right',
    ),
  };
  const navigationGroup = ownerDocument.createElement('div');
  navigationGroup.className = 'keyboard-navigation';
  navigationGroup.setAttribute('role', 'group');
  navigationGroup.setAttribute('aria-label', 'Move cursor');
  navigationGroup.append(
    navigationButtons.left,
    navigationButtons.right,
    navigationButtons.up,
    navigationButtons.down,
  );
  keyboardTitle.append(keyboardTitleText, navigationGroup);

  const layoutPicker = ownerDocument.createElement('div');
  layoutPicker.className = 'keyboard-layout-picker';
  layoutPicker.dataset.open = 'false';
  const layoutTrigger = ownerDocument.createElement('button');
  layoutTrigger.className = 'keyboard-layout-trigger';
  layoutTrigger.id = `keyboard-layout-trigger-${instanceId}`;
  layoutTrigger.type = 'button';
  layoutTrigger.textContent = 'Khmer';
  layoutTrigger.setAttribute(
    'aria-controls',
    `keyboard-layout-menu-${instanceId}`,
  );
  layoutTrigger.setAttribute('aria-expanded', 'false');
  layoutTrigger.setAttribute('aria-haspopup', 'menu');
  layoutTrigger.setAttribute('aria-label', 'Choose keyboard layout');
  layoutTrigger.setAttribute('title', 'Choose keyboard layout');
  const layoutMenu = ownerDocument.createElement('div');
  layoutMenu.className = 'keyboard-layout-menu';
  layoutMenu.hidden = true;
  layoutMenu.id = `keyboard-layout-menu-${instanceId}`;
  layoutMenu.setAttribute('aria-label', 'Keyboard layout choices');
  layoutMenu.setAttribute('role', 'menu');
  layoutMenu.append(
    createLayoutOption(
      ownerDocument,
      instanceId,
      'khmer',
      'Khmer NiDA',
      'Use Khmer NiDA keyboard layout',
    ),
    createLayoutOption(
      ownerDocument,
      instanceId,
      'english',
      'English (US)',
      'Use English keyboard layout',
    ),
  );
  layoutPicker.append(layoutTrigger, layoutMenu);

  const keyboardStatus = ownerDocument.createElement('div');
  keyboardStatus.className = 'keyboard-status';
  const keyboardMode = ownerDocument.createElement('span');
  keyboardMode.className = 'visually-hidden';
  keyboardMode.id = `keyboard-mode-${instanceId}`;
  keyboardMode.textContent = 'Normal';
  const spaceMode = ownerDocument.createElement('span');
  spaceMode.className = 'visually-hidden';
  spaceMode.id = `space-mode-${instanceId}`;
  spaceMode.textContent = 'Space: ZWSP';
  const minimizeButton = createWindowButton(
    ownerDocument,
    `minimize-khmer-keyboard-${instanceId}`,
    '▾',
    'Minimize keyboard',
  );
  minimizeButton.setAttribute('aria-pressed', 'false');

  keyboardStatus.append(keyboardMode, spaceMode, minimizeButton);
  keyboardHeader.append(
    closeButton,
    keyboardTitle,
    layoutPicker,
    keyboardStatus,
  );

  const keyboardRows = ownerDocument.createElement('div');
  keyboardRows.className = 'keyboard-grid';
  keyboardRows.id = `keyboard-rows-${instanceId}`;

  const keyboardFooter = ownerDocument.createElement('div');
  keyboardFooter.className = 'keyboard-footer';
  keyboardFooter.textContent =
    'NiDA layout with default zero-width space behavior for Khmer word breaks.';

  const resizeHandle = ownerDocument.createElement('div');
  resizeHandle.className = 'keyboard-resize-handle';
  resizeHandle.id = `keyboard-resize-handle-${instanceId}`;
  resizeHandle.setAttribute('aria-hidden', 'true');

  keyboard.append(keyboardHeader, keyboardRows, keyboardFooter, resizeHandle);

  return {
    closeButton,
    keyboard,
    keyboardFooter,
    keyboardMode,
    keyboardRows,
    keyboardTitle: keyboardTitleText,
    layoutMenu,
    layoutTrigger,
    minimizeButton,
    navigationButtons,
    resizeHandle,
    spaceMode,
  };
}

function mountKhmerNiDAKeyboard({
  editor,
  monaco,
  onStateChange,
  ownerDocument,
  ownerWindow,
  preferences,
  refs,
}) {
  if (!editor) {
    throw new Error('Khmer NiDA keyboard plugin requires an editor instance.');
  }

  const instanceId = 'editor-khmer-nida';
  const anchorElement =
    editor.getDomNode?.() ||
    refs?.editorHost ||
    ownerDocument.querySelector('[data-ol-ref="editor"]');

  if (!anchorElement) {
    throw new Error(
      'Khmer NiDA keyboard plugin could not find the editor host.',
    );
  }

  const elements = createKhmerKeyboardElements(ownerDocument, instanceId);
  const targetAdapter = createMonacoInputAdapter(editor, {
    source: 'open-lyric-khmer-nida-keyboard',
    shouldTriggerSuggestOnInsert(text) {
      return (
        Boolean(String(text ?? '').trim()) &&
        isEditorOnlyAutoSuggestEnabled(ownerDocument)
      );
    },
  });
  const keyboardVisibleContextKey = editor.createContextKey(
    KEYBOARD_CONTEXT_KEY,
    false,
  );
  const persistedKeyboardWindowState =
    preferences?.loadKeyboardWindowPreference?.(KEYBOARD_PREFERENCE_ID) ?? null;
  const keyboardToggleKeybindings =
    monaco?.KeyMod && monaco?.KeyCode
      ? [monaco.KeyMod.CtrlCmd | monaco.KeyMod.Alt | monaco.KeyCode.KeyK]
      : [];
  let shouldPersistKeyboardState = false;

  const keyboardController = createKhmerNidaKeyboard({
    ...elements,
    anchorElement,
    closeOnOutsidePointerDown: false,
    mountToBody: true,
    onStateChange(keyboardState) {
      keyboardVisibleContextKey.set(Boolean(keyboardState?.isOpen));

      if (shouldPersistKeyboardState) {
        preferences?.saveKeyboardWindowPreference?.(
          KEYBOARD_PREFERENCE_ID,
          keyboardState,
        );
      }

      onStateChange?.(keyboardState);
    },
    ownerDocument,
    ownerWindow,
    target: targetAdapter,
  });

  shouldPersistKeyboardState = true;
  if (persistedKeyboardWindowState) {
    keyboardController.restoreState?.(persistedKeyboardWindowState);
  }

  const openAction = editor.addAction({
    id: 'open-lyric.open-khmer-keyboard',
    label: `Open Khmer Keyboard`,
    precondition: `!${KEYBOARD_CONTEXT_KEY}`,
    contextMenuGroupId: '9_cutcopypaste',
    contextMenuOrder: 7,
    keybindings: keyboardToggleKeybindings,
    run: () => {
      keyboardController.open();
    },
  });
  const closeAction = editor.addAction({
    id: 'open-lyric.close-khmer-keyboard',
    label: `Hide Khmer Keyboard`,
    precondition: KEYBOARD_CONTEXT_KEY,
    contextMenuGroupId: '9_cutcopypaste',
    contextMenuOrder: 7,
    keybindings: keyboardToggleKeybindings,
    run: () => {
      keyboardController.close();
    },
  });

  return {
    close() {
      keyboardController.close();
    },
    destroy() {
      openAction.dispose();
      closeAction.dispose();
      keyboardController.destroy();
      elements.keyboard.remove();
      targetAdapter.destroy?.();
    },
    getState() {
      return keyboardController.getState();
    },
    open() {
      keyboardController.open();
    },
    toggle() {
      keyboardController.toggle();
    },
  };
}

const kmKhKeyboardPluginData = {
  actionLabel: 'Khmer Keyboard',
  create: mountKhmerNiDAKeyboard,
  displayName: 'Khmer NiDA Keyboard',
  id: KEYBOARD_PREFERENCE_ID,
};

export { kmKhKeyboardPluginData };
